class Solution {
public:
    int takeCharacters(std::string s, int k) {
        std::vector<int> counts(3, 0);
        for (char c : s) counts[c - 'a']++;
        for (int i = 0; i < 3; ++i) {
            if (counts[i] < k) return -1;
        }
        std::vector<int> max_rem(3);
        for (int i = 0; i < 3; ++i) max_rem[i] = counts[i] - k;

        std::vector<int> cur(3, 0);
        int max_len = 0, left = 0;
        int n = s.size();
        for (int right = 0; right < n; ++right) {
            int ch = s[right] - 'a';
            cur[ch]++;
            while (cur[ch] > max_rem[ch]) {
                cur[s[left] - 'a']--;
                left++;
            }
            max_len = std::max(max_len, right - left + 1);
        }
        return n - max_len;
    }
};

class Solution {
    public int takeCharacters(String s, int k) {
        int[] counts = new int[3];
        int n = s.length();
        for (int i = 0; i < n; i++) counts[s.charAt(i) - 'a']++;
        for (int i = 0; i < 3; i++) {
            if (counts[i] < k) return -1;
        }
        int[] maxRem = new int[3];
        for (int i = 0; i < 3; i++) maxRem[i] = counts[i] - k;

        int[] cur = new int[3];
        int maxLen = 0, left = 0;
        for (int right = 0; right < n; right++) {
            int ch = s.charAt(right) - 'a';
            cur[ch]++;
            while (cur[ch] > maxRem[ch]) {
                cur[s.charAt(left) - 'a']--;
                left++;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return n - maxLen;
    }
}

var takeCharacters = function(s, k) {
    const counts = [0, 0, 0];
    const n = s.length;
    for (let i = 0; i < n; i++) counts[s.charCodeAt(i) - 97]++;
    for (let i = 0; i < 3; i++) {
        if (counts[i] < k) return -1;
    }
    const maxRem = counts.map(c => c - k);
    const cur = [0, 0, 0];
    let maxLen = 0, left = 0;
    for (let right = 0; right < n; right++) {
        const ch = s.charCodeAt(right) - 97;
        cur[ch]++;
        while (cur[ch] > maxRem[ch]) {
            cur[s.charCodeAt(left) - 97]--;
            left++;
        }
        if (right - left + 1 > maxLen) maxLen = right - left + 1;
    }
    return n - maxLen;
